SELECT hd_income_band_sk, hd_vehicle_count, w_state, wp_type, avg_discount, avg_profit, total_sales, CASE WHEN avg_profit > 100 THEN 'Excellent' WHEN avg_profit > 50 THEN 'Good' WHEN avg_profit > 20 THEN 'Average' ELSE 'Poor' END AS profit_category, DENSE_RANK() OVER (ORDER BY avg_profit DESC) AS profit_rank FROM ( SELECT hd.hd_income_band_sk, hd.hd_vehicle_count, w.w_state, wp.wp_type, AVG(ws.ws_ext_discount_amt) AS avg_discount, AVG(ws.ws_net_profit) AS avg_profit, COUNT(*) AS total_sales FROM web_sales ws JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk JOIN web_page wp ON ws.ws_web_page_sk = wp.wp_web_page_sk GROUP BY hd.hd_income_band_sk, hd.hd_vehicle_count, w.w_state, wp.wp_type ) t ORDER BY profit_rank
